using UnityEngine;
namespace MetaPort.Games.SmashDrums { public class SmashDrumsManager : MonoBehaviour { public Transform[] drums = new Transform[4]; void Awake(){ for(int i=0;i<4;i++){ var go=GameObject.CreatePrimitive(PrimitiveType.Cylinder); go.name=$"Drum_{i}"; go.transform.SetParent(transform,false); go.transform.localPosition=new Vector3((i-1.5f)*0.4f,0.8f,1.5f); go.transform.localScale=new Vector3(0.3f,0.15f,0.3f); var mat=new Material(Shader.Find("MetaPort/Icon3D")); mat.SetColor("_BaseColor", Color.HSVToRGB(i*0.25f,0.8f,0.9f)); go.GetComponent<Renderer>().material=mat; drums[i]=go.transform; go.AddComponent<Drum>().index=i; } } } public class Drum:MonoBehaviour{ public int index; void OnTriggerEnter(Collider other){ Debug.Log($"[SmashDrums] Hit drum {index}"); transform.localScale*=1.2f; LeanTween.scale(gameObject, Vector3.one*0.3f,0.1f); } } public static class LeanTween{ public static LTDescr scale(GameObject go, Vector3 to,float t)=>new LTDescr(go,to,t); public class LTDescr{ GameObject go; Vector3 target; float time; public LTDescr(GameObject g,Vector3 tar,float tm){go=g;target=tar;time=tm; g.GetComponent<MonoBehaviour>()?.StartCoroutine(Anim());} System.Collections.IEnumerator Anim(){ Vector3 start=go.transform.localScale; float e=0; while(e<time){e+=Time.deltaTime; go.transform.localScale=Vector3.Lerp(start,target,e/time); yield return null;} } } } }
